<?php
require_once "../db.php"; require_role("Student"); $id=(int)($_GET["id"]??0);$uid=current_id();
$st=$conn->prepare("SELECT h.*,q.title,q.subject FROM quiz_history h JOIN quiz q ON q.id=h.quiz_id WHERE h.id=? AND h.student_id=?");$st->bind_param("ii",$id,$uid);$st->execute();$d=$st->get_result()->fetch_assoc();if(!$d)die("Result not found.");
$p=$d["total_questions"]?round($d["score"]/$d["total_questions"]*100,1):0;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quiz Result</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card panel-card"><div class="card-body p-5 text-center"><h2 class="fw-bold"><?=e($d["title"])?></h2><div class="score-circle my-4"><strong><?=$p?>%</strong><span>Score</span></div><h4><?=$d["score"]?> / <?=$d["total_questions"]?></h4><div class="row g-3 mt-3"><div class="col-md-4"><div class="stat-card p-3"><b><?=$d["attempted_questions"]?></b><br><small>Attempted</small></div></div><div class="col-md-4"><div class="stat-card p-3"><b class="text-success"><?=$d["correct_answers"]?></b><br><small>Correct</small></div></div><div class="col-md-4"><div class="stat-card p-3"><b class="text-danger"><?=$d["wrong_answers"]?></b><br><small>Wrong</small></div></div></div><div class="mt-4"><a href="dashboard.php" class="btn btn-primary">Dashboard</a><a href="quiz_history.php" class="btn btn-outline-primary ms-2">History</a></div></div></div></div></body></html>
